            grades.putAll(loaded);
        }
    }
    /** Records the grade from the date (replacing one recorded from that same date), to be written on save. */
    public void recordGrade(LocalDate from, String grade) {
        grades.put(from, grade);
        recorded = java.util.Map.entry(from, grade);
    }
    /** The grade this edit recorded and has not written yet; null when none. */
    public java.util.Map.Entry<LocalDate, String> getRecordedGrade() { return recorded; }
    public void clearRecordedGrade() { recorded = null; }
    public LocalDate getToday() { return today; }
    public void setToday(LocalDate today) { this.today = today; }
    public int getVersion() { return version; }
    /** The person's own terms in days; null when none. */
    public Integer getTerms() { return terms; }
    public void setTerms(Integer terms) { this.terms = terms; }
    /** Sets the terms the form gave, noting whether they differ from those the person had (a save giving the
     *  terms they already had changes nothing, even while dated terms are in force on the sheet's today — except a
     *  save giving none while dated terms are in force, which counts as a change of the terms shown). */
    public void editTerms(Integer terms) {
        termsChanged = !java.util.Objects.equals(this.terms, terms) || (terms == null && termsOn(today) != null);
        this.terms = terms;
    }
    public boolean isTermsChanged() { return termsChanged; }
    /** The person's terms dated from a from-date on (null terms: none from then), each until the next; before the
     *  first, {@link #getTerms()} are in force. */
    private final java.util.TreeMap<LocalDate, Integer> datedTerms = new java.util.TreeMap<>();
    /** Terms recorded by this edit and not yet written: their from-date. */
    private LocalDate recordedTermsFrom;
    public java.util.SortedMap<LocalDate, Integer> getDatedTerms() { return java.util.Collections.unmodifiableSortedMap(datedTerms); }
    public void setDatedTerms(java.util.Map<LocalDate, Integer> loaded) {
        datedTerms.clear();
        datedTerms.putAll(loaded);
    }
    /** Records the terms from the date (replacing those recorded from that same date), to be written on save. */
    public void recordTerms(LocalDate from, Integer terms) {
        termsChanged = !datedTerms.containsKey(from) || !java.util.Objects.equals(datedTerms.get(from), terms);
        datedTerms.put(from, terms);
        recordedTermsFrom = from;
