import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { readPath, useAsOf } from '../asof/useAsOf';

/** `version` goes up on every save; an editor sends back the version it loaded, so a save over
 *  someone else's newer one is refused. `statementCount` is how many statements were taken;
 *  `statedTotal` is the last one's due-total ("n/a" possible, "" when none) and `statementDate` the
 *  sheet's today when it was taken ("" when none). `retired` is whether a retirement date is set
 *  (retired at once, whatever the date) and `retiredFrom` is that date ("" when none). `held` is
 *  whether the person has any hold and `holds` lists each (from, to; to "" when open-ended): their
 *  OPEN claims dated within one, unless bound by a statement, count in no live total. `patrons` are the
 *  names of the people they named as patrons, sorted, and `patronIds` those people's ids. `grade`
 *  is the grade in force on the sheet's today when loaded and `grades` every grade recorded. */
export type Person = {
  id: string;
  name: string;
  grade: string;
  version: number;
  statementCount: number;
  statedTotal: string;
  statementDate: string;
  retired: boolean;
  retiredFrom: string;
  held: boolean;
  holds: HoldFrom[];
  patrons: string[];
  patronIds: string[];
  grades: GradeFrom[];
  /** The person's own terms in days in force on the sheet's today; "" for none. */
  terms: string;
  /** The person's own terms in days from the beginning of time (before any dated terms); "" for none. */
  baseTerms: string;
  /** The reason of a steward's flag while the sheet's today is on or before its until date; "" otherwise. While
   *  it shows, only a steward may open the person's claims. */
  flag?: string;
  /** The user who may approve or reject the person's PENDING claims as a steward may; "" for none. */
  approver?: string;
  /** The person's contact, trimmed and lower-cased; "" for none. */
  contact: string;
  /** The person's tags, lower-cased, sorted and comma separated ("a,b"); "" for none. */
  tags: string;
  /** The person's aliases, sorted as names are compared. */
  aliases: string[];
  /** Whether the person's name or an alias is used by someone else on a sheet of the sheet's tree. */
  clashing: boolean;
  /** The sheet the person was transferred from; "" for anyone else. */
  origin: string;
  /** The person's past retirements, each "<from> to <the day unretired>", in the order they ended: no claim of
   *  theirs may be dated after the from and before the to of one. */
  retirements: string[];
  /** The person's SNAPSHOT lines, each "<the day being left> <due-total>" ("n/a" for none), oldest first. */
  snapshots: string[];
  /** Their statements still standing, each "<statement date> <due-total>", oldest first. */
  statements: string[];
};

/** A hold from a date to a date, both included (YYYY-MM-DD; to "" when open-ended). */
export type HoldFrom = { from: string; to: string };

/** Whether one of the person's holds covers the date. */

